def resolve(path, cwd, links):
    link_count = [0]

    def helper(path, cwd):
        if not path.startswith('/'):
            path = cwd.rstrip('/') + '/' + path

        parts = path.split('/')
        result = []
        components = parts[::-1]  # stack, pop from end for front processing

        while components:
            comp = components.pop()
            if comp == '' or comp == '.':
                continue
            elif comp == '..':
                if result:
                    result.pop()
            else:
                result.append(comp)
                current = '/' + '/'.join(result)
                if current in links:
                    link_count[0] += 1
                    if link_count[0] > 8:
                        return None
                    target = links[current]
                    if not target.startswith('/'):
                        dir_path = '/' + '/'.join(result[:-1])
                        target = dir_path.rstrip('/') + '/' + target if dir_path != '/' else '/' + target
                    # remove the link component itself, will be replaced by target resolution
                    result.pop()
                    new_parts = target.split('/')
                    components.extend(new_parts[::-1])

        if not result:
            return '/'
        return '/' + '/'.join(result)

    return helper(path, cwd)

